extern "C" QW VelocityXfAtPos(void *, int, QW);

void RecalcSwXpMovement(SW *psw, int cpxp, XP **apxp) {
    int ixpd;
    for (int ipxp = 0; ipxp < cpxp; ipxp++) {
        XP *pxp = apxp[ipxp];
        XPD *pxpd = pxp->axpd;
        ixpd = 0;
        do {
            if (pxpd->pxf) {
                pxpd->vel = VelocityXfAtPos(pxpd->pxf, 0, pxpd->pos);
                pxpd->pso->Slot56(pxp, ixpd);
            }
            ixpd++;
            pxpd++;
        } while (ixpd < 2);
        ixpd = 0;
        pxpd = pxp->axpd;
        SO **ppso = &pxpd->pso;
        do {
            SO *pso = *ppso;
            if (pso) pso->Slot57(pxp, ixpd);
            ixpd++;
            ppso += 0x10;
        } while (ixpd < 2);
        pxp->velRel = VectorSub(pxp->axpd[0].vel, pxp->axpd[1].vel);
    }
}

